<template>
  <div class="goods-management">
    <!-- 操作栏 -->
    <div class="action-bar">
      <div class="search-box">
        <svg class="search-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor">
          <circle cx="11" cy="11" r="8"></circle>
          <path d="m21 21-4.35-4.35"></path>
        </svg>
        <input
          v-model="searchKeyword"
          type="text"
          placeholder="搜索商品名称..."
          class="search-input"
          @keyup.enter="handleSearch"
        />
      </div>
      <button @click="showAddDialog = true" class="add-btn">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor">
          <line x1="12" y1="5" x2="12" y2="19"></line>
          <line x1="5" y1="12" x2="19" y2="12"></line>
        </svg>
        添加商品
      </button>
    </div>

    <!-- 商品列表 -->
    <div class="goods-table-wrapper">
      <table class="goods-table">
        <thead>
          <tr>
            <th>商品ID</th>
            <th>商品名称</th>
            <th>分类</th>
            <th>价格</th>
            <th>库存</th>
            <th>销量</th>
            <th>状态</th>
            <th style="width: 200px;">操作</th>
          </tr>
        </thead>
        <tbody>
          <tr v-for="item in goodsList" :key="item.id">
            <td>{{ item.id }}</td>
            <td>
              <div class="goods-info">
                <img :src="item.mainPicUrl || '/images/goods/ml.png'" :alt="item.name" class="goods-image" />
                <span>{{ item.name }}</span>
              </div>
            </td>
            <td>{{ item.categoryName || '-' }}</td>
            <td class="price">¥{{ item.price }}</td>
            <td>
              <span :class="{ 'low-stock': item.stock < 10 }">
                {{ item.stock || 0 }}
              </span>
            </td>
            <td>{{ item.sold || 0 }}</td>
            <td>
              <span 
                class="status-badge" 
                :class="item.isValid ? 'active' : 'inactive'"
                @click="handleToggleStatus(item)"
                style="cursor: pointer;"
              >
                {{ item.isValid ? '上架' : '下架' }}
              </span>
            </td>
            <td>
              <div class="action-buttons">
                <button @click="handleEdit(item)" class="btn-edit">编辑</button>
                <button @click="handleViewComments(item)" class="btn-comment">评论</button>
                <button @click="handleDelete(item.id)" class="btn-delete">删除</button>
              </div>
            </td>
          </tr>
        </tbody>
      </table>

      <div v-if="goodsList.length === 0" class="empty-state">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor">
          <circle cx="12" cy="12" r="10"></circle>
          <line x1="12" y1="8" x2="12" y2="12"></line>
          <line x1="12" y1="16" x2="12.01" y2="16"></line>
        </svg>
        <p>暂无商品数据</p>
      </div>
    </div>

    <!-- 分页 -->
    <div class="pagination" v-if="total > 0">
      <button @click="handlePageChange(currentPage - 1)" :disabled="currentPage === 1" class="page-btn">
        上一页
      </button>
      <span class="page-info">第 {{ currentPage }} / {{ totalPages }} 页</span>
      <button @click="handlePageChange(currentPage + 1)" :disabled="currentPage === totalPages" class="page-btn">
        下一页
      </button>
    </div>

    <!-- 图片裁剪对话框 -->
    <van-popup v-model:show="showCropperDialog" position="center" :style="{ width: '90%', maxWidth: '600px', borderRadius: '16px' }">
      <div class="dialog">
        <div class="dialog-header">
          <h3>裁剪图片</h3>
          <button @click="closeCropper" class="close-btn">×</button>
        </div>
        <div class="dialog-body">
          <div class="cropper-container">
            <img ref="cropperImageElement" :src="cropperImage" class="cropper-image" />
          </div>
          <div class="cropper-tip">
            <p>💡 操作提示：</p>
            <ul>
              <li>鼠标滚轮：缩放图片</li>
              <li>拖动图片：调整位置</li>
              <li>拖动裁剪框：调整裁剪区域</li>
            </ul>
          </div>
        </div>
        <div class="dialog-footer">
          <button @click="closeCropper" class="btn-cancel">取消</button>
          <button @click="confirmCrop" class="btn-confirm">确定裁剪</button>
        </div>
      </div>
    </van-popup>

    <!-- 添加/编辑对话框 -->
    <van-popup v-model:show="showAddDialog" position="center" :style="{ width: '90%', maxWidth: '600px', borderRadius: '16px' }">
      <div class="dialog">
        <div class="dialog-header">
          <h3>{{ editingGoods ? '编辑商品' : '添加商品' }}</h3>
          <button @click="closeDialog" class="close-btn">×</button>
        </div>
        <div class="dialog-body">
          <div class="form-group">
            <label>商品名称 <span class="required">*</span></label>
            <input v-model="formData.name" type="text" placeholder="请输入商品名称" />
          </div>
          
          <div class="form-row">
            <div class="form-group">
              <label>商品分类</label>
              <select v-model="formData.categoryId" class="form-select">
                <option :value="null">未分类</option>
                <option v-for="cat in categoryList" :key="cat.id" :value="cat.id">
                  {{ cat.name }}
                </option>
              </select>
            </div>
            <div class="form-group">
              <label>销售单位</label>
              <input v-model="formData.unit" type="text" placeholder="如：件、盒、袋" />
            </div>
          </div>
          
          <div class="form-row">
            <div class="form-group">
              <label>商品价格 <span class="required">*</span></label>
              <input v-model="formData.price" type="number" step="0.01" placeholder="请输入价格" />
            </div>
            <div class="form-group">
              <label>库存数量 <span class="required">*</span></label>
              <input v-model="formData.stock" type="number" placeholder="请输入库存" />
            </div>
          </div>
          
          <div class="form-row">
            <div class="form-group">
              <label>发货地</label>
              <input v-model="formData.shippingOrigin" type="text" placeholder="如：上海" />
            </div>
            <div class="form-group">
              <label>邮费（元）</label>
              <input v-model="formData.postage" type="number" step="0.01" placeholder="0表示包邮" />
            </div>
          </div>
          
          <div class="form-group">
            <label>商品主图</label>
            <div class="image-upload-area">
              <div v-if="formData.mainPicUrl" class="uploaded-image">
                <img :src="getImageUrl(formData.mainPicUrl)" alt="主图预览" />
                <div class="image-actions">
                  <button type="button" @click="handleReupload" class="btn-reupload">重新上传</button>
                  <button type="button" @click="formData.mainPicUrl = ''" class="btn-remove">删除</button>
                </div>
              </div>
              <div v-else class="upload-placeholder" @click="triggerFileInput">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor">
                  <rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect>
                  <circle cx="8.5" cy="8.5" r="1.5"></circle>
                  <polyline points="21 15 16 10 5 21"></polyline>
                </svg>
                <span>点击上传图片</span>
                <span class="upload-tip">建议尺寸：1:1，支持jpg、png格式，最大5MB</span>
              </div>
              <input 
                ref="fileInput" 
                type="file" 
                accept="image/*" 
                @change="handleFileSelect" 
                style="display: none;"
              />
            </div>
          </div>
          
          <div class="form-group">
            <label>商品描述</label>
            <textarea v-model="formData.msg" placeholder="请输入商品简短描述" rows="2"></textarea>
          </div>
          
          <div class="form-group">
            <label>商品详情（支持HTML）</label>
            <textarea v-model="formData.detail" placeholder="请输入商品详细信息，支持HTML格式" rows="6"></textarea>
          </div>
        </div>
        <div class="dialog-footer">
          <button @click="closeDialog" class="btn-cancel">取消</button>
          <button @click="handleSubmit" class="btn-confirm">确定</button>
        </div>
      </div>
    </van-popup>
  </div>
</template>

<script setup>
import { ref, onMounted, nextTick, watch } from 'vue';
import { useRouter } from 'vue-router';
import { 
  updateProductStatus, 
  getProductComments, 
  getProductList,
  addProduct,
  updateProduct,
  deleteProduct,
  getCategoryList,
  uploadGoodsImage
} from '@/api/merchant';
import { showConfirmDialog, showSuccessToast, showFailToast, showToast } from 'vant';

const router = useRouter();

const searchKeyword = ref('');
const goodsList = ref([]);
const categoryList = ref([]);
const currentPage = ref(1);
const pageSize = ref(10);
const total = ref(0);
const totalPages = ref(0);

const showAddDialog = ref(false);
const showCropperDialog = ref(false);
const editingGoods = ref(null);
const fileInput = ref(null);
const cropperImageElement = ref(null);
const cropperImage = ref('');
let cropperInstance = null;

const formData = ref({
  name: '',
  categoryId: null,
  price: '',
  stock: '',
  unit: '',
  shippingOrigin: '上海',
  postage: 0,
  mainPicUrl: '',
  msg: '',
  detail: ''
});

const loadCategoryList = async () => {
  try {
    const result = await getCategoryList();
    if (result && result.code === 200) {
      categoryList.value = result.data || [];
    }
  } catch (error) {
    console.error('加载分类列表失败:', error);
  }
};

const loadGoodsList = async () => {
  try {
    const params = {
      page: currentPage.value,
      pageSize: pageSize.value
    };
    
    if (searchKeyword.value) {
      params.keyword = searchKeyword.value;
    }
    
    const result = await getProductList(params);
    
    if (result && result.code === 200) {
      goodsList.value = result.data.records || [];
      total.value = result.data.total || 0;
      totalPages.value = result.data.pages || 0;
    } else {
      showFailToast(result.msg || '加载失败');
    }
  } catch (error) {
    console.error('加载商品列表失败:', error);
    showFailToast('加载失败');
  }
};

const handleSearch = () => {
  currentPage.value = 1;
  loadGoodsList();
};

const handlePageChange = (page) => {
  if (page >= 1 && page <= totalPages.value) {
    currentPage.value = page;
    loadGoodsList();
  }
};

const handleEdit = (item) => {
  editingGoods.value = item;
  formData.value = {
    id: item.id,
    name: item.name,
    categoryId: item.categoryId,
    price: item.price,
    stock: item.stock || 0,
    unit: item.unit || '',
    shippingOrigin: item.shippingOrigin || '上海',
    postage: item.postage || 0,
    mainPicUrl: item.mainPicUrl || '',
    msg: item.msg || '',
    detail: item.detail || ''
  };
  showAddDialog.value = true;
};

const handleDelete = (id) => {
  showConfirmDialog({
    title: '确认删除',
    message: '确定要删除这个商品吗？',
    confirmButtonColor: '#ff6b6b'
  }).then(async () => {
    try {
      const result = await deleteProduct(id);
      if (result && result.code === 200) {
        showSuccessToast('删除成功');
        loadGoodsList();
      } else {
        showFailToast(result.msg || '删除失败');
      }
    } catch (error) {
      showFailToast('删除失败');
    }
  }).catch(() => {});
};

const handleToggleStatus = async (item) => {
  const newStatus = !item.isValid;
  const action = newStatus ? '上架' : '下架';
  
  try {
    const result = await updateProductStatus(item.id, newStatus);
    if (result && result.code === 200) {
      showSuccessToast(`${action}成功`);
      item.isValid = newStatus;
    } else {
      showFailToast(result.msg || `${action}失败`);
    }
  } catch (error) {
    showFailToast(`${action}失败`);
  }
};

const handleViewComments = (item) => {
  router.push(`/merchant/products/${item.id}/comments`);
};

const handleSubmit = async () => {
  if (!formData.value.name || !formData.value.price) {
    showFailToast('请填写商品名称和价格');
    return;
  }
  
  if (!formData.value.stock && formData.value.stock !== 0) {
    showFailToast('请填写库存数量');
    return;
  }

  try {
    const data = {
      name: formData.value.name,
      categoryId: formData.value.categoryId,
      price: parseFloat(formData.value.price),
      stock: parseInt(formData.value.stock) || 0,
      unit: formData.value.unit || '',
      shippingOrigin: formData.value.shippingOrigin || '上海',
      postage: parseFloat(formData.value.postage) || 0,
      mainPicUrl: formData.value.mainPicUrl || '',
      msg: formData.value.msg || '',
      detail: formData.value.detail || ''
    };
    
    let result;
    if (editingGoods.value) {
      // 编辑商品
      result = await updateProduct(editingGoods.value.id, data);
    } else {
      // 添加商品
      result = await addProduct(data);
    }
    
    if (result && result.code === 200) {
      showSuccessToast(editingGoods.value ? '更新成功' : '添加成功');
      closeDialog();
      loadGoodsList();
    } else {
      showFailToast(result.msg || '操作失败');
    }
  } catch (error) {
    showFailToast('操作失败');
  }
};

const closeDialog = () => {
  showAddDialog.value = false;
  editingGoods.value = null;
  formData.value = {
    name: '',
    categoryId: null,
    price: '',
    stock: '',
    unit: '',
    shippingOrigin: '上海',
    postage: 0,
    mainPicUrl: '',
    msg: '',
    detail: ''
  };
};

// 图片上传相关
const triggerFileInput = () => {
  fileInput.value?.click();
};

const handleReupload = () => {
  fileInput.value?.click();
};

const handleFileSelect = (event) => {
  const file = event.target.files[0];
  if (!file) return;
  
  // 验证文件类型
  if (!file.type.startsWith('image/')) {
    showToast('请选择图片文件');
    return;
  }
  
  // 验证文件大小（限制5MB）
  if (file.size > 5 * 1024 * 1024) {
    showToast('图片大小不能超过5MB');
    return;
  }
  
  // 读取文件并显示裁剪器
  const reader = new FileReader();
  reader.onload = (e) => {
    cropperImage.value = e.target.result;
    showCropperDialog.value = true;
    
    // 等待DOM更新后初始化裁剪器
    nextTick(() => {
      initCropper();
    });
  };
  reader.readAsDataURL(file);
  
  // 清空input，允许重复选择同一文件
  event.target.value = '';
};

const initCropper = async () => {
  if (!cropperImageElement.value) return;
  
  // 动态导入 cropperjs
  try {
    const { default: Cropper } = await import('cropperjs');
    
    // 动态加载 CSS
    if (!document.getElementById('cropper-css')) {
      const link = document.createElement('link');
      link.id = 'cropper-css';
      link.rel = 'stylesheet';
      link.href = 'https://cdn.jsdelivr.net/npm/cropperjs@1.6.1/dist/cropper.min.css';
      document.head.appendChild(link);
    }
    
    // 销毁旧的实例
    if (cropperInstance) {
      cropperInstance.destroy();
    }
    
    // 创建新的裁剪器实例
    cropperInstance = new Cropper(cropperImageElement.value, {
      aspectRatio: 1, // 1:1 比例
      viewMode: 1, // 限制裁剪框在画布内
      dragMode: 'move', // 拖动模式：移动图片
      autoCropArea: 0.8, // 自动裁剪区域占比
      restore: false,
      guides: true, // 显示网格线
      center: true, // 显示中心指示器
      highlight: true,
      cropBoxMovable: true, // 裁剪框可移动
      cropBoxResizable: true, // 裁剪框可调整大小
      toggleDragModeOnDblclick: true, // 双击切换拖动模式
      background: true,
      modal: true,
      responsive: true,
      checkOrientation: true,
      checkCrossOrigin: true,
    });
  } catch (error) {
    console.error('加载裁剪器失败:', error);
    showFailToast('图片裁剪功能加载失败，请刷新页面重试');
  }
};

const confirmCrop = async () => {
  if (!cropperInstance) return;
  
  try {
    // 获取裁剪后的canvas
    const canvas = cropperInstance.getCroppedCanvas({
      width: 800, // 输出宽度
      height: 800, // 输出高度
      imageSmoothingEnabled: true,
      imageSmoothingQuality: 'high',
    });
    
    // 将canvas转换为blob
    canvas.toBlob(async (blob) => {
      try {
        // 创建File对象
        const file = new File([blob], 'goods-image.jpg', { type: 'image/jpeg' });
        
        // 上传到服务器
        showToast({
          message: '正在上传图片...',
          duration: 0,
          forbidClick: true,
        });
        
        const result = await uploadGoodsImage(file);
        
        if (result && result.code === 200) {
          // 保存服务器返回的图片URL
          formData.value.mainPicUrl = result.data.url;
          closeCropper();
          showSuccessToast('图片上传成功');
        } else {
          showFailToast(result.msg || '图片上传失败');
        }
      } catch (error) {
        console.error('上传图片失败:', error);
        showFailToast('图片上传失败');
      }
    }, 'image/jpeg', 0.9); // JPEG格式，质量90%
  } catch (error) {
    console.error('裁剪图片失败:', error);
    showFailToast('图片裁剪失败');
  }
};

const closeCropper = () => {
  if (cropperInstance) {
    cropperInstance.destroy();
    cropperInstance = null;
  }
  showCropperDialog.value = false;
  cropperImage.value = '';
};

// 获取完整图片URL
const getImageUrl = (url) => {
  if (!url) return '';
  // 如果是完整URL，直接返回
  if (url.startsWith('http://') || url.startsWith('https://')) {
    return url;
  }
  // 如果是相对路径，拼接服务器地址
  return `http://localhost:8081${url}`;
};

onMounted(() => {
  loadCategoryList();
  loadGoodsList();
});
</script>

<style scoped>
